using SmartSpare.AppHost;

var builder = DistributedApplication.CreateBuilder(args);

// Same major version as Azure Database for PostgreSQL Flexible Server. The admin password is
// generated by Aspire and kept in the AppHost user secrets, never in the repository.
// The database itself is not created by Aspire: the migration runner runs the cluster bootstrap
// (roles, database owned by smartspare_owner), exactly as on a real server.
// db/ is mounted read-only so the "Load demo data" command can run T001 with the container's psql.
var postgres = builder.AddPostgres("postgres")
    .WithImageTag("17")
    .WithDataVolume("smartspare-postgres17-data")
    .WithContainerName(DemoDataCommand.ContainerName)
    .WithBindMount("../../db", "/db", isReadOnly: true);

// Passwords of the login roles created by db/bootstrap/000_bootstrap_cluster.sql; generated once
// and persisted in the AppHost user secrets.
var migratorPassword = GeneratedSecret("migrator-password");
var apiPassword = GeneratedSecret("api-password");
var jobsPassword = GeneratedSecret("jobs-password");
var reportingPassword = GeneratedSecret("reporting-password");

// Password of the T001 demo users (issue #33): generated once and persisted in the AppHost user secrets;
// shown under Parameters in the dashboard, or set your own with `dotnet user-secrets set Parameters:demo-user-password`.
var demoUserPassword = GeneratedSecret("demo-user-password");

// Bootstrap (first start only) + EF migrations of all contexts in catalogue order, then exit.
var migrations = builder.AddProject<Projects.SmartSpare_MigrationRunner>("migrations")
    .WithReference(postgres)
    .WithEnvironment("Migrations__Passwords__Migrator", migratorPassword)
    .WithEnvironment("Migrations__Passwords__Api", apiPassword)
    .WithEnvironment("Migrations__Passwords__Jobs", jobsPassword)
    .WithEnvironment("Migrations__Passwords__Reporting", reportingPassword)
    .WaitFor(postgres);

// "Load demo data" on the postgres resource: T001 + set-demo-passwords with the connection and
// passwords Aspire already holds, so nothing has to be copied from the dashboard (issue #33).
DemoDataCommand.Add(postgres, migratorPassword, demoUserPassword, new Projects.SmartSpare_MigrationRunner().ProjectPath);

// The application connects as smartspare_api (role app_write): never as owner or superuser.
var endpoint = postgres.Resource.PrimaryEndpoint;
var database = builder.AddConnectionString("smartspare", ReferenceExpression.Create(
    $"Host={endpoint.Property(EndpointProperty.Host)};Port={endpoint.Property(EndpointProperty.Port)};Database=smartspare;Username=smartspare_api;Password={apiPassword}"));

builder.AddProject<Projects.SmartSpare_Host>("host")
    .WithReference(database)
    .WaitForCompletion(migrations)
    .WithHttpHealthCheck("/health/ready");

await builder.Build().RunAsync().ConfigureAwait(false);

IResourceBuilder<ParameterResource> GeneratedSecret(string name) =>
    builder.AddParameter(name, new GenerateParameterDefault { MinLength = 24, Special = false }, secret: true, persist: true);
